contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(to != address(0));
        require(address(this).balance >= amount);
        require(amount > 0);

        // ensure c holds some Ether so that migrateTo has something to move
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 beforeBal = address(c).balance;

        bool reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The invariant: if migrateTo reverted, c's balance is unchanged; otherwise c's balance is zero.
        // Also, when it succeeds, the destination must have received the entire beforeBal.
        assert(!reverted
            ? (address(c).balance == 0)
            : (address(c).balance == beforeBal));
    }

    receive() external payable {}
}

